-- PostgreSQL component checks with synthetic SQL request claims only. All DDL,
-- entitlements, fixtures, plans, jobs and rows are rolled back by the runner.
CREATE TEMP TABLE sandy_provisioning_samples(operation text PRIMARY KEY,result jsonb);
CREATE FUNCTION pg_temp.sandy_provisioning_sample(p_operation text,p_arguments jsonb,p_request_id uuid) RETURNS jsonb LANGUAGE plpgsql AS $sample$
DECLARE value jsonb;BEGIN value:=public.sandy_customer_provisioning_execute(p_operation,p_arguments,p_request_id);IF value->>'ok'='true' THEN INSERT INTO pg_temp.sandy_provisioning_samples(operation,result) VALUES(p_operation,value) ON CONFLICT(operation) DO UPDATE SET result=excluded.result;END IF;RETURN value;END $sample$;
DO $test$
DECLARE actor uuid:=gen_random_uuid();other_actor uuid:=gen_random_uuid();customer uuid;other_customer uuid;result jsonb;again jsonb;plan jsonb;job uuid;resource_id uuid;table_name text;request uuid:=gen_random_uuid();version integer;checks integer:=0;
BEGIN
 IF has_function_privilege('anon','public.sandy_customer_provisioning_execute(text,jsonb,uuid)','EXECUTE') OR has_function_privilege('authenticated','public.sandy_provisioning_workspace_verified(uuid)','EXECUTE') OR has_table_privilege('authenticated','public.sandy_customer_resources','SELECT') OR has_table_privilege('authenticated','public.sandy_provisioning_customer_policies','UPDATE') OR has_table_privilege('service_role','public.sandy_customer_provisioning_events','UPDATE') THEN RAISE EXCEPTION 'provisioning privilege boundary';END IF;checks:=checks+5;
 INSERT INTO auth.users(id,email,email_confirmed_at,is_anonymous,raw_app_meta_data,raw_user_meta_data) VALUES(actor,'sandy-provisioning-'||actor||'@example.invalid',clock_timestamp(),false,'{"provider":"email","providers":["email"]}','{"sandy_api_isolated_session_test":true}'),(other_actor,'sandy-provisioning-'||other_actor||'@example.invalid',clock_timestamp(),false,'{"provider":"email","providers":["email"]}','{"sandy_api_isolated_session_test":true}');
 PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',actor,'role','authenticated')::text,true);
 result:=public.sandy_customer_onboarding_execute('customer.onboarding.ensure','{}',gen_random_uuid());customer:=(result->>'customer_id')::uuid;
 result:=pg_temp.sandy_provisioning_sample('customer.provisioning.features.list','{}',gen_random_uuid());IF result->>'ok' IS DISTINCT FROM 'true' THEN RAISE EXCEPTION 'feature definitions';END IF;checks:=checks+1;
 result:=pg_temp.sandy_provisioning_sample('customer.provisioning.plan','{"template_key":"customer.workspace"}',gen_random_uuid());IF result->>'error' IS DISTINCT FROM 'provisioning_template_unavailable' THEN RAISE EXCEPTION 'disabled template';END IF;checks:=checks+1;
 UPDATE public.sandy_provisioning_features SET enabled=true WHERE feature_key='database.workspace';UPDATE public.sandy_provisioning_templates SET enabled=true WHERE template_key='customer.workspace';
 result:=pg_temp.sandy_provisioning_sample('customer.provisioning.templates.list','{}',gen_random_uuid());IF result->>'ok' IS DISTINCT FROM 'true' THEN RAISE EXCEPTION 'reusable templates';END IF;checks:=checks+1;
 result:=pg_temp.sandy_provisioning_sample('customer.provisioning.plan','{"template_key":"customer.workspace"}',gen_random_uuid());IF result->>'error' IS DISTINCT FROM 'provisioning_feature_not_entitled' THEN RAISE EXCEPTION 'missing entitlement';END IF;checks:=checks+1;
 INSERT INTO public.sandy_commerce_entitlements(customer_id,feature_key,reason,expires_at) VALUES(customer,'database.workspace','Isolated rolled-back provisioning verification',clock_timestamp()+interval '1 hour');
 INSERT INTO public.sandy_provisioning_customer_policies(customer_id,feature_key,enabled) VALUES(customer,'database.workspace',true);
 result:=pg_temp.sandy_provisioning_sample('customer.provisioning.plan','{"template_key":"customer.workspace"}',request);IF result->>'ok' IS DISTINCT FROM 'true' THEN RAISE EXCEPTION 'immutable plan: %',result;END IF;checks:=checks+1;plan:=result->'result'->'plan';
 again:=pg_temp.sandy_provisioning_sample('customer.provisioning.plan','{"template_key":"customer.workspace"}',request);IF again->>'reused' IS DISTINCT FROM 'true' OR again->'result'->'plan'->>'id'<>plan->>'id' THEN RAISE EXCEPTION 'plan idempotency';END IF;checks:=checks+1;
 UPDATE public.sandy_provisioning_customer_policies SET resource_limit=0 WHERE customer_id=customer;
 again:=pg_temp.sandy_provisioning_sample('customer.provisioning.execute',jsonb_build_object('plan_id',plan->>'id','plan_sha256',plan->>'snapshot_sha256'),gen_random_uuid());IF again->>'error' IS DISTINCT FROM 'provisioning_policy_changed' THEN RAISE EXCEPTION 'policy change at execution';END IF;checks:=checks+1;
 again:=pg_temp.sandy_provisioning_sample('customer.provisioning.plan','{"template_key":"customer.workspace"}',gen_random_uuid());IF again->>'error' IS DISTINCT FROM 'provisioning_resource_quota_exceeded' THEN RAISE EXCEPTION 'resource quota';END IF;checks:=checks+1;
 UPDATE public.sandy_provisioning_customer_policies SET resource_limit=1 WHERE customer_id=customer;
 result:=pg_temp.sandy_provisioning_sample('customer.provisioning.plan','{"template_key":"customer.workspace"}',gen_random_uuid());plan:=result->'result'->'plan';
 UPDATE public.sandy_commerce_entitlements SET revoked_at=clock_timestamp() WHERE customer_id=customer AND feature_key='database.workspace';
 again:=pg_temp.sandy_provisioning_sample('customer.provisioning.execute',jsonb_build_object('plan_id',plan->>'id','plan_sha256',plan->>'snapshot_sha256'),gen_random_uuid());IF again->>'error' IS DISTINCT FROM 'provisioning_policy_changed' THEN RAISE EXCEPTION 'entitlement revoked after plan';END IF;checks:=checks+1;
 UPDATE public.sandy_commerce_entitlements SET revoked_at=NULL WHERE customer_id=customer AND feature_key='database.workspace';
 request:=gen_random_uuid();result:=pg_temp.sandy_provisioning_sample('customer.provisioning.execute',jsonb_build_object('plan_id',plan->>'id','plan_sha256',plan->>'snapshot_sha256'),request);IF result->>'ok' IS DISTINCT FROM 'true' OR result->'result'->'job'->>'state' IS DISTINCT FROM 'succeeded' THEN RAISE EXCEPTION 'actual workspace provisioning: %',result;END IF;checks:=checks+1;
 resource_id:=(result->'result'->'job'->'resource_ids'->>0)::uuid;job:=(result->'result'->'job'->>'id')::uuid;table_name:='sandy_workspace_'||replace(resource_id::text,'-','');
 again:=pg_temp.sandy_provisioning_sample('customer.provisioning.jobs.get',jsonb_build_object('job_id',job),gen_random_uuid());IF again->'result'->'job'->>'id' IS DISTINCT FROM job::text THEN RAISE EXCEPTION 'persisted job';END IF;checks:=checks+1;
 again:=pg_temp.sandy_provisioning_sample('customer.resources.list','{}',gen_random_uuid());IF jsonb_array_length(again->'result'->'resources')<>1 THEN RAISE EXCEPTION 'owned resource registry';END IF;checks:=checks+1;
 IF to_regclass('public.'||table_name) IS NULL OR NOT public.sandy_provisioning_workspace_verified(resource_id) THEN RAISE EXCEPTION 'actual provider resource/ACL verification';END IF;checks:=checks+2;
 again:=pg_temp.sandy_provisioning_sample('customer.provisioning.execute',jsonb_build_object('plan_id',plan->>'id','plan_sha256',plan->>'snapshot_sha256'),request);IF again->>'reused' IS DISTINCT FROM 'true' OR again->'result'->'job'->>'id' IS DISTINCT FROM job::text THEN RAISE EXCEPTION 'provision idempotency';END IF;checks:=checks+1;
 again:=pg_temp.sandy_provisioning_sample('customer.provisioning.execute',jsonb_build_object('plan_id',plan->>'id','plan_sha256',plan->>'snapshot_sha256'),gen_random_uuid());IF again->>'reused' IS DISTINCT FROM 'true' OR (SELECT count(*) FROM public.sandy_customer_resources WHERE customer_id=customer)<>1 THEN RAISE EXCEPTION 'plan single execution/duplicate provider resource';END IF;checks:=checks+1;
 again:=pg_temp.sandy_provisioning_sample('customer.workspace.records.upsert',jsonb_build_object('resource_id',resource_id,'key','fixture','value','{"hello":"Sandy"}'::jsonb,'expected_version',0),gen_random_uuid());IF again->>'ok' IS DISTINCT FROM 'true' OR again->'result'->>'version' IS DISTINCT FROM '1' THEN RAISE EXCEPTION 'actual data write: %',again;END IF;checks:=checks+1;
 again:=pg_temp.sandy_provisioning_sample('customer.workspace.records.get',jsonb_build_object('resource_id',resource_id,'key','fixture'),gen_random_uuid());IF again->'result'->'record'->'value'->>'hello' IS DISTINCT FROM 'Sandy' THEN RAISE EXCEPTION 'actual data result';END IF;checks:=checks+1;
 again:=pg_temp.sandy_provisioning_sample('customer.workspace.records.upsert',jsonb_build_object('resource_id',resource_id,'key','fixture','value','{}'::jsonb,'expected_version',0),gen_random_uuid());IF again->>'error' IS DISTINCT FROM 'workspace_record_version_conflict' THEN RAISE EXCEPTION 'data compare and swap';END IF;checks:=checks+1;
 UPDATE public.sandy_provisioning_customer_policies SET storage_bytes_limit=65536 WHERE customer_id=customer;
 again:=pg_temp.sandy_provisioning_sample('customer.workspace.records.upsert',jsonb_build_object('resource_id',resource_id,'key','large','value',jsonb_build_object('data',repeat('x',65500)),'expected_version',0),gen_random_uuid());IF again->>'ok' IS DISTINCT FROM 'true' THEN RAISE EXCEPTION 'within current quota rejected: %',again;END IF;checks:=checks+1;
 again:=pg_temp.sandy_provisioning_sample('customer.workspace.records.upsert',jsonb_build_object('resource_id',resource_id,'key','large','value',jsonb_build_object('data',repeat('x',65520)),'expected_version',1),gen_random_uuid());IF again->>'error' IS DISTINCT FROM 'workspace_storage_quota_exceeded' THEN RAISE EXCEPTION 'current storage quota at write: %',again;END IF;checks:=checks+1;
 again:=pg_temp.sandy_provisioning_sample('customer.workspace.records.delete',jsonb_build_object('resource_id',resource_id,'key','large','expected_version',1),gen_random_uuid());IF again->'result'->>'deleted' IS DISTINCT FROM 'true' THEN RAISE EXCEPTION 'quota fixture cleanup: %',again;END IF;checks:=checks+1;
 PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',other_actor,'role','authenticated')::text,true);
 again:=public.sandy_customer_onboarding_execute('customer.onboarding.ensure','{}',gen_random_uuid());other_customer:=(again->>'customer_id')::uuid;
 again:=pg_temp.sandy_provisioning_sample('customer.provisioning.jobs.get',jsonb_build_object('job_id',job),gen_random_uuid());IF again->>'error' IS DISTINCT FROM 'provisioning_job_not_found' THEN RAISE EXCEPTION 'cross customer job';END IF;checks:=checks+1;
 again:=pg_temp.sandy_provisioning_sample('customer.workspace.records.get',jsonb_build_object('resource_id',resource_id,'key','fixture'),gen_random_uuid());IF again->>'error' IS DISTINCT FROM 'customer_resource_not_found' THEN RAISE EXCEPTION 'cross customer data';END IF;checks:=checks+1;
 PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',actor,'role','authenticated')::text,true);
 EXECUTE format('ALTER TABLE public.%I DISABLE ROW LEVEL SECURITY',table_name);
 again:=pg_temp.sandy_provisioning_sample('customer.resources.reconcile',jsonb_build_object('resource_id',resource_id),gen_random_uuid());IF again->'result'->'resource'->>'state' IS DISTINCT FROM 'drifted' OR again->'result'->>'effect_confirmed' IS DISTINCT FROM 'false' THEN RAISE EXCEPTION 'truthful actual drift';END IF;checks:=checks+1;version:=(again->'result'->'resource'->>'version')::integer;
 again:=pg_temp.sandy_provisioning_sample('customer.workspace.records.get',jsonb_build_object('resource_id',resource_id,'key','fixture'),gen_random_uuid());IF again->>'error' IS DISTINCT FROM 'resource_reconciliation_required' THEN RAISE EXCEPTION 'drift blocks data';END IF;checks:=checks+1;
 again:=pg_temp.sandy_provisioning_sample('customer.resources.recover',jsonb_build_object('resource_id',resource_id,'expected_version',version),gen_random_uuid());IF again->'result'->'resource'->>'state' IS DISTINCT FROM 'ready' OR NOT public.sandy_provisioning_workspace_verified(resource_id) THEN RAISE EXCEPTION 'actual policy recovery';END IF;checks:=checks+1;version:=(again->'result'->'resource'->>'version')::integer;
 UPDATE public.sandy_provisioning_features SET enabled=false WHERE feature_key='database.workspace';
 again:=pg_temp.sandy_provisioning_sample('customer.workspace.records.upsert',jsonb_build_object('resource_id',resource_id,'key','new','value','{}'::jsonb,'expected_version',0),gen_random_uuid());IF again->>'error' IS DISTINCT FROM 'provisioning_feature_not_entitled' THEN RAISE EXCEPTION 'disabled feature blocks writes';END IF;checks:=checks+1;
 again:=pg_temp.sandy_provisioning_sample('customer.workspace.records.get',jsonb_build_object('resource_id',resource_id,'key','fixture'),gen_random_uuid());IF again->>'ok' IS DISTINCT FROM 'true' THEN RAISE EXCEPTION 'disabled feature preserves retained data read';END IF;checks:=checks+1;
 again:=pg_temp.sandy_provisioning_sample('customer.workspace.records.delete',jsonb_build_object('resource_id',resource_id,'key','fixture','expected_version',1),gen_random_uuid());IF again->'result'->>'deleted' IS DISTINCT FROM 'true' THEN RAISE EXCEPTION 'retention data deletion';END IF;checks:=checks+1;
 SELECT r.version INTO version FROM public.sandy_customer_resources r WHERE r.id=resource_id;
 again:=pg_temp.sandy_provisioning_sample('customer.resources.decommission',jsonb_build_object('resource_id',resource_id,'expected_version',version,'delete_data',false),gen_random_uuid());IF again->>'error' IS DISTINCT FROM 'explicit_data_deletion_required' THEN RAISE EXCEPTION 'explicit decommission policy';END IF;checks:=checks+1;
 again:=pg_temp.sandy_provisioning_sample('customer.resources.decommission',jsonb_build_object('resource_id',resource_id,'expected_version',version,'delete_data',true),gen_random_uuid());IF again->'result'->'resource'->>'state' IS DISTINCT FROM 'decommissioned' OR to_regclass('public.'||table_name) IS NOT NULL THEN RAISE EXCEPTION 'actual provider decommission';END IF;checks:=checks+2;
 again:=pg_temp.sandy_provisioning_sample('customer.resources.recover',jsonb_build_object('resource_id',resource_id,'expected_version',version),gen_random_uuid());IF again->>'error' IS DISTINCT FROM 'resource_version_conflict' THEN RAISE EXCEPTION 'no destructive resurrection';END IF;checks:=checks+1;
 UPDATE public.sandy_provisioning_features SET enabled=true WHERE feature_key='database.workspace';
 result:=pg_temp.sandy_provisioning_sample('customer.provisioning.plan','{"template_key":"customer.workspace"}',gen_random_uuid());plan:=result->'result'->'plan';
 EXECUTE $ddl$CREATE FUNCTION pg_temp.sandy_test_provisioning_failure() RETURNS trigger LANGUAGE plpgsql AS $fn$ BEGIN IF NEW.state='succeeded' THEN RAISE EXCEPTION 'isolated_provisioning_job_failure';END IF;RETURN NEW;END $fn$$ddl$;
 CREATE TRIGGER sandy_test_job_failure BEFORE INSERT ON public.sandy_customer_provisioning_jobs FOR EACH ROW EXECUTE FUNCTION pg_temp.sandy_test_provisioning_failure();
 again:=pg_temp.sandy_provisioning_sample('customer.provisioning.execute',jsonb_build_object('plan_id',plan->>'id','plan_sha256',plan->>'snapshot_sha256'),gen_random_uuid());
 IF again->>'error' IS DISTINCT FROM 'provisioning_transaction_failed' OR again->>'executed' IS DISTINCT FROM 'false' OR again->>'job_id' IS NULL THEN RAISE EXCEPTION 'failed transaction did not return structured failed job: %',again;END IF;checks:=checks+1;
 DROP TRIGGER sandy_test_job_failure ON public.sandy_customer_provisioning_jobs;
 IF EXISTS(SELECT 1 FROM public.sandy_customer_resources WHERE customer_id=customer AND state<>'decommissioned') OR EXISTS(SELECT 1 FROM pg_class WHERE obj_description(oid,'pg_class') LIKE 'sandy_customer_resource:%:'||customer::text) THEN RAISE EXCEPTION 'failed job left provider resource or orphan';END IF;checks:=checks+2;
 IF NOT EXISTS(SELECT 1 FROM public.sandy_customer_provisioning_jobs WHERE plan_id=(plan->>'id')::uuid AND state='failed' AND cardinality(resource_ids)=0 AND error_code='provisioning_transaction_failed') THEN RAISE EXCEPTION 'failed provider transaction did not retain truthful failed job';END IF;checks:=checks+1;
 result:=pg_temp.sandy_provisioning_sample('customer.provisioning.jobs.get',jsonb_build_object('job_id',again->>'job_id'),gen_random_uuid());IF result->'result'->'job'->>'state' IS DISTINCT FROM 'failed' THEN RAISE EXCEPTION 'failed job status';END IF;checks:=checks+1;
 result:=pg_temp.sandy_provisioning_sample('customer.provisioning.plan','{"template_key":"customer.workspace"}',gen_random_uuid());plan:=result->'result'->'plan';
 UPDATE public.sandy_customer_provisioning_plans SET expires_at=clock_timestamp()-interval '1 second' WHERE id=(plan->>'id')::uuid;
 again:=pg_temp.sandy_provisioning_sample('customer.provisioning.execute',jsonb_build_object('plan_id',plan->>'id','plan_sha256',plan->>'snapshot_sha256'),gen_random_uuid());IF again->>'error' IS DISTINCT FROM 'provisioning_plan_stale' THEN RAISE EXCEPTION 'expired immutable plan';END IF;checks:=checks+1;
 UPDATE public.sandy_memory_portal_accounts SET revoked_at=clock_timestamp() WHERE auth_user_id=actor;
 again:=pg_temp.sandy_provisioning_sample('customer.provisioning.execute',jsonb_build_object('plan_id',plan->>'id','plan_sha256',plan->>'snapshot_sha256'),request);IF again->>'error' IS DISTINCT FROM 'verified_customer_access_required' THEN RAISE EXCEPTION 'revoked receipt replay';END IF;checks:=checks+1;
 IF EXISTS(SELECT 1 FROM public.sandy_customer_resources WHERE customer_id=customer AND actual_cost_microusd IS NOT NULL) THEN RAISE EXCEPTION 'unknown billing presented as zero actual cost';END IF;checks:=checks+1;
 CREATE TEMP TABLE sandy_provisioning_test_report AS SELECT checks passed,0 failed,true rolled_back;
END $test$;
SELECT t.*,(SELECT jsonb_object_agg(operation,result) FROM sandy_provisioning_samples) samples FROM sandy_provisioning_test_report t;
